using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Threading;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Windows.Forms;using Musikbox;using MusikboxTests;
class StudioFix55Tests {
 static int count;static void Check(bool b,string t){if(!b)throw new Exception(t);count++;Console.WriteLine("OK "+t);}
 static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
 static void Call(object o,string n,params object[] a){o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}
 static Control[] All(Control p){return p.Controls.Cast<Control>().SelectMany(c=>new[]{c}.Concat(All(c))).ToArray();}
 static void Pump(){for(int i=0;i<8;i++){Application.DoEvents();Thread.Sleep(15);}}
 static void Wait(Func<bool> condition){var until=DateTime.UtcNow.AddSeconds(8);while(!condition()&&DateTime.UtcNow<until)Pump();Check(condition(),"Vorschau vollständig geladen");}
 [DllImport("libX11.so.6")]static extern IntPtr XOpenDisplay(string n);
 [DllImport("libX11.so.6")]static extern int XFlush(IntPtr d);
 [DllImport("libX11.so.6")]static extern int XSetInputFocus(IntPtr d,IntPtr w,int revert,IntPtr time);
 [DllImport("libX11.so.6")]static extern byte XKeysymToKeycode(IntPtr d,IntPtr k);
 [DllImport("libXtst.so.6")]static extern int XTestFakeMotionEvent(IntPtr d,int screen,int x,int y,IntPtr delay);
 [DllImport("libXtst.so.6")]static extern int XTestFakeButtonEvent(IntPtr d,uint b,bool down,IntPtr delay);
 [DllImport("libXtst.so.6")]static extern int XTestFakeKeyEvent(IntPtr d,uint key,bool down,IntPtr delay);
 static IntPtr display;
 static void Key(int sym,bool down){XTestFakeKeyEvent(display,XKeysymToKeycode(display,new IntPtr(sym)),down,IntPtr.Zero);XFlush(display);Pump();}
 static void Click(Control control,Point pt){pt=control.PointToScreen(pt);XTestFakeMotionEvent(display,-1,pt.X,pt.Y,IntPtr.Zero);XTestFakeButtonEvent(display,1,true,IntPtr.Zero);XTestFakeButtonEvent(display,1,false,IntPtr.Zero);XFlush(display);Pump();}
 static void Row(MainView v,int row){var r=v.Songs.GetCellDisplayRectangle(1,row,false);Click(v.Songs,new Point(r.Left+20,r.Top+r.Height/2));}
 static CoverSearchView Search(string image){return new CoverSearchView("Lainey Wilson","4x4xU",false,(a,t,m,n,c)=>new List<CoverMatch>{new CoverMatch{Artist="Lainey Wilson",Release="Whirlwind"}},(m,c)=>image);}
 static void Preview(CoverSearchView d){d.Find.PerformClick();Wait(()=>d.Results.Items.Count==1);d.Results.SelectedIndex=0;Wait(()=>d.Apply.Enabled);}
 [STAThread]static void Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);string image=Path.Combine(root,"cover.jpg");using(var bmp=new Bitmap(240,240)){using(var g=Graphics.FromImage(bmp))g.Clear(Color.Purple);bmp.Save(image,System.Drawing.Imaging.ImageFormat.Jpeg);}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);display=XOpenDisplay(null);Check(display!=IntPtr.Zero,"Echte Maus- und Tastaturereignisse über XTest verfügbar");
  using(var v=new MainView(Path.Combine(root,"layout.json"))){var controller=new Controller(v,Path.Combine(root,"backups"),new Playback(new PlaybackTestDevice()));var p=new Project();p.Folders.Add(new BoxFolder{Name="000 Test",Theme="Test",Songs=new List<Song>{new Song{Artist="Lainey Wilson",Title="4x4xU",Album="Neue Musik",Source="missing-a.mp3"},new Song{Artist="Lainey Wilson",Title="Wildflowers and Wild Horses (Official Music Video) mit sehr langem Zusatz",Album="Ein sehr langes Album mit vielen weiteren Wörtern",Source="missing-b.mp3"},new Song{Artist="Glen Campbell",Title="Sunflower",Album="Country",Source="missing-c.mp3"}}});Call(controller,"ReplaceProject",p,null,true);v.Show();v.WindowState=FormWindowState.Normal;v.ClientSize=new Size(1525,784);Pump();var library=(Control)Field(v,"libraryCard");var now=(Control)Field(v,"nowCard");var table=(Control)Field(v,"tableCard");int height=library.Height,top=table.Top;
   Row(v,0);Check(v.Songs.SelectedRows.Count==1&&v.Songs.Rows[0].Selected,"Einfacher Klick wählt genau einen Titel");Row(v,1);Check(v.Songs.SelectedRows.Count==1&&v.Songs.Rows[1].Selected,"Zweiter einfacher Klick ersetzt die vorherige Auswahl");Check(library.Height==height&&now.Height==height&&table.Top==top&&v.TagPane.Top==top,"Langer Titel lässt beide Karten und die darunterliegenden Kanten unverändert");
   Key(0xffe3,true);Row(v,0);Key(0xffe3,false);Check(v.Songs.SelectedRows.Count==2,"Strg-Klick erweitert weiterhin die Auswahl");Row(v,0);Key(0xffe1,true);Row(v,2);Key(0xffe1,false);Check(v.Songs.SelectedRows.Count==3,"Shift-Klick wählt weiterhin einen Bereich");Row(v,1);Check(v.Songs.SelectedRows.Count==1&&v.Songs.Rows[1].Selected,"Normaler Klick beendet auch eine Bereichsauswahl");
   v.SetVoiceState(true,"Mikrofon aktiv");Check(((StudioActionButton)v.Microphone).Active&&v.Microphone.AccessibleName.Contains("beenden"),"Mikrofonzustand wird vom tatsächlich gezeichneten Button verwendet");v.SetVoiceState(false,"Beendet");Check(!((StudioActionButton)v.Microphone).Active,"Mikrofonanzeige wird nach Stop zurückgesetzt");
   typeof(Controller).GetField("dirty",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(controller,false);v.Close();
  }
  using(var d=Search(image)){d.Show();Pump();foreach(var size in new[]{new Size(860,590),new Size(1400,850)}){d.Size=size;Pump();var top=All(d).OfType<TableLayoutPanel>().First();var note=top.Controls.OfType<Label>().First();Check(note.Bottom<=d.ArtistName.Parent.PointToClient(d.ArtistName.PointToScreen(Point.Empty)).Y,"Hinweis und Suchzeilen überlappen bei Fensterbreite "+size.Width+" nicht");Check(d.TitleName.Bottom<=d.FreeName.Top,"Eingabezeilen bleiben getrennt");}d.Font=new Font("Segoe UI",14);d.Size=new Size(900,700);Pump();var panel=All(d).OfType<TableLayoutPanel>().First();var label=panel.Controls.OfType<Label>().First();Check(label.Height>=label.GetPreferredSize(new Size(label.Width,0)).Height,"Hinweis bleibt bei größerer Schrift vollständig sichtbar");Preview(d);Check(d.AcceptButton==d.Apply&&d.Apply.Text=="Cover übernehmen","Übernahme ist eindeutiger Standardknopf nach Bildauswahl");using(var shot=new Bitmap(d.Width,d.Height)){using(var g=Graphics.FromImage(shot))g.CopyFromScreen(d.Location,Point.Empty,shot.Size);shot.Save(Path.Combine(root,"cover-grosse-schrift.png"));}d.Apply.PerformClick();Check(d.DialogResult==DialogResult.OK&&d.SelectedArtwork==image,"Übernahme per Button erhält bestätigten Bildpfad nach Schließen");}
  using(var d=Search(image)){d.Show();Preview(d);d.Results.Focus();XSetInputFocus(display,d.Handle,1,IntPtr.Zero);XFlush(display);Key(0xff0d,true);Key(0xff0d,false);Pump();Check(d.DialogResult==DialogResult.OK&&d.SelectedArtwork==image,"Echte Enter-Taste in Ergebnisliste bestätigt das Cover endgültig");}
  using(var d=Search(image)){d.Show();Preview(d);d.Close();Check(d.SelectedArtwork==null&&d.DialogResult!=DialogResult.OK,"Schließen ohne Bestätigung verwirft den Bildpfad");}
  using(var d=new TitleCoverChoiceView(new Song{Artist="Lainey Wilson",Title="4x4xU"},image,null,s=>{var child=Search(image);child.Shown+=(a,e)=>{Preview(child);child.Apply.PerformClick();};return child;})){d.Show();Pump();All(d).OfType<Button>().Single(b=>b.Name=="SingleCoverSearch").PerformClick();Check(d.DialogResult==DialogResult.OK&&d.SelectedArtwork==image,"Bestätigung in Coversuche bestätigt auch den übergeordneten Titelcoverdialog");}
  Console.WriteLine("BESTANDEN: "+count+" gezielte UI-Prüfungen; Mono/Xvfb, keine Windows-Abnahme.");
 }
}
